<section class="page-intro"><span class="eyebrow">A PLACE OF YOUR OWN</span><h1>Hello, <?= e($user['name']) ?>.</h1><p>Keep your details and orders close.</p></section><section class="section account-layout"><div class="panel"><h2>Your details</h2><form method="post" action="/account"><?= csrf_field() ?><label>Name<input name="name" value="<?= e($user['name']) ?>" required maxlength="120"></label><label>Phone<input name="phone" value="<?= e($user['phone']) ?>" maxlength="40"></label><p><?= e($user['email']) ?></p><details><summary>Change password</summary><label>Current password<input name="current_password" type="password" autocomplete="current-password"></label><label>New password<input name="new_password" type="password" minlength="12" autocomplete="new-password"></label></details><button class="button">Save my details</button></form><?php if(in_array($user['role'],['owner','admin','developer'],true)): ?><p><a class="text-link" href="/admin">Open store management</a></p><?php endif ?><form action="/logout" method="post"><?= csrf_field() ?><button class="text-button">Sign out</button></form></div><div><?php require ROOT.'/app/views/welcome-account.php'; ?><h2>Your orders</h2><?php $orders=rows('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC',[$user['id']]);if(!$orders): ?><div class="empty-state"><p>Your first little favorite is waiting.</p><a class="button" href="/shop">Explore the collection</a></div><?php endif ?><?php foreach($orders as $o): ?><a class="account-order panel" href="/confirmation/<?= e($o['id']) ?>"><strong><?= e($o['reference']) ?></strong><span class="status-tag" data-order-status="<?= e($o['status']) ?>"><?= e(ucwords(str_replace('_',' ',$o['status']))) ?></span><span><?= e($o['currency']) ?> <?= number_format($o['total']/100,2) ?></span><small>Delivery: <?= e($o['currency']) ?> <?= number_format($o['delivery_fee']/100,2) ?><?php $deliveryHistory=json_decode($o['delivery_snapshot']??'{}',true)?:[];if(!empty($deliveryHistory['name'])): ?> · <?= e($deliveryHistory['name']) ?><?php endif ?></small><?php if(variants_ready()):foreach(rows('SELECT product_name,variant_snapshot FROM order_items WHERE order_id=? AND variant_snapshot IS NOT NULL',[$o['id']]) as $historyItem):$v=json_decode($historyItem['variant_snapshot'],true); ?><small><?= e($historyItem['product_name'].' · '.implode(' · ',array_filter([$v['color']??null,$v['size']??null,$v['sku']??null]))) ?></small><?php endforeach;endif ?><small><?= e($o['created_at']) ?> UTC</small></a><?php endforeach ?></div></section>
